fast_pseudocode:
# Grid lambda reads autotuned tile sizes; no explicit XBLOCK/YBLOCK kwargs
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 512, 'YBLOCK': 1}, num_warps=4),
        triton.Config({'XBLOCK': 256, 'YBLOCK': 2}, num_warps=4),
        triton.Config({'XBLOCK': 256, 'YBLOCK': 4}, num_warps=8),
        triton.Config({'XBLOCK': 128, 'YBLOCK': 8}, num_warps=4),
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...

grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']), cdiv(ynumel, meta['YBLOCK']))
kernel[grid](in_ptr, out_ptr, ynumel, xnumel)  # autotune injects XBLOCK/YBLOCK automatically

# Autotuned block size, same grid structure
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 128}, num_warps=4),
        triton.Config({'XBLOCK': 256}, num_warps=4),
        triton.Config({'XBLOCK': 512}, num_warps=8),
        triton.Config({'XBLOCK': 1024}, num_warps=8),
    ],
    key=['xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, xnumel, XBLOCK: tl.constexpr):
    xindex = tl.program_id(0) * XBLOCK + tl.arange(0, XBLOCK)
    ...

grid = lambda meta: (cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](in_ptr, out_ptr, xnumel)

